// CRITICAL SAFETY OVERRIDE: Never send to sample CSV email addresses!
// All outbound notification emails are strictly redirected to controlled test inboxes.
const items = $input.all();
const importId = $('Notification Webhook Trigger').item.json.body.import_id;
const testRecipient = $env.TEST_EMAIL_RECIPIENTS || 'developer-test-inbox@example.com';
const deliveryMode = $env.DELIVERY_MODE || 'test';

const formattedMessages = [];

for (const item of items) {
  const data = item.json;
  const userName = data.user_name || data.external_user_id;

  let productListHtml = '';
  let productListText = '';

  for (const prod of (data.matched_products || [])) {
    const rates = (prod.rate_min && prod.rate_max) ? `${prod.rate_min}% - ${prod.rate_max}% p.a.` : 'Published bank rates apply';
    productListText += `• ${prod.product_name} (${prod.source_name}) | Rate: ${rates} | Link: ${prod.source_url}\n`;
    productListHtml += `<li><strong>${prod.product_name}</strong> (${prod.source_name})<br/>Indicative Rate: ${rates}<br/><a href="${prod.source_url}">View Product Details</a></li><br/>`;
  }

  const textBody = `Hello ${userName},\n\nBased on our automated matching criteria, you may be eligible for the following personal loan products:\n\n${productListText}\n\nDISCLAIMER: Matches are indicative and do not guarantee credit approval. Final terms are determined solely by the lender upon application verification.`;
  const htmlBody = `<h3>Hello ${userName},</h3><p>Based on our automated matching criteria, you may be eligible for the following personal loan products:</p><ul>${productListHtml}</ul><p style="color: #64748b; font-size: 12px;"><strong>DISCLAIMER:</strong> Matches are indicative and do not guarantee credit approval. Final terms are determined solely by the lender.</p>`;

  formattedMessages.push({
    json: {
      import_id: importId,
      user_id: data.user_id,
      delivery_mode: deliveryMode,
      safe_recipient: testRecipient,
      original_sample_email: data.original_sample_email,
      matched_count: data.matched_count,
      subject: `Loan Eligibility Engine: ${data.matched_count} Indicative Loan Matches Found`,
      text_body: textBody,
      html_body: htmlBody
    }
  });
}

return formattedMessages;

parameters.query:
INSERT INTO notifications (
  import_id, user_id, delivery_mode, test_recipient, matched_products_count, status, provider_message_id, sent_at
) VALUES (
  $1::uuid, $2::uuid, $3, $4, $5, 'SENT', 'ses-mock-msg-' || gen_random_uuid(), NOW()
)
RETURNING id, test_recipient, status, provider_message_id;
